const event = $input.first().json;
const text = (value) => String(value ?? '').trim();
const orderNumber = text(event.order_number);
const email = text(event.email);
const productId = text(event.product_id);
const priceMinor = Number(event.price);
const currency = text(event.currency).toUpperCase();
const productName = text(event.product_name);
const saleDate = text(event.sale_timestamp || event.created_at);
const errors = [];
if (!orderNumber) errors.push('Missing order_number');
if (!email || !email.includes('@')) errors.push('Missing or invalid email');
if (!productId) errors.push('Missing product_id');
if (!Number.isSafeInteger(priceMinor) || priceMinor < 0) errors.push('Invalid price');
if (!currency) errors.push('Missing currency');
if (!saleDate || Number.isNaN(Date.parse(saleDate))) errors.push('Missing or invalid sale_timestamp');
let amount;
if (currency) {
  try {
    const fractionDigits = new Intl.NumberFormat('en-US', { style: 'currency', currency }).resolvedOptions().maximumFractionDigits;
    amount = priceMinor / (10 ** fractionDigits);
  } catch {
    errors.push('Invalid currency code');
  }
}
if (errors.length) throw new Error(`Sale rejected before Airtable write: ${errors.join('; ')}`);
const fields = {
  'Order Number': orderNumber,
  'Sale ID': text(event.sale_id || event.id),
  'Buyer Email': email,
  'Product ID': productId,
  'Product Name': productName,
  'Sale Amount': amount,
  'Currency': currency.toLowerCase(),
  'Can Contact': event.can_contact === true,
  'Sale Date': saleDate,
};
return [{ json: { requestBody: { performUpsert: { fieldsToMergeOn: ['Order Number'] }, records: [{ fields }] } } }];
